import { Component, Element, Event, EventEmitter, h, Host, Listen, Prop, State, Watch } from '@stencil/core';
import { Rel, Target, TreeViewSize } from '../../../types';
import { verifyTarget } from '../../../utils/link-helper';

/**
 * @slot label - label slot for the text content of the tree node
 * @slot default - default slot for nested tree nodes
 */
@Component({
  tag: 'groupui-tree-node',
  styleUrl: 'tree-node.scss',
  shadow: true,
})
export class TreeNode {
  @Element() host: HTMLElement;

  /**
   * If true, the tree node is disabled
   */
  @Prop({ reflect: true }) readonly disabled: boolean = false;

  /**
   * If true, the tree node is active
   */
  @Prop({ reflect: true }) readonly active: boolean = false;

  /**
   * If true, the tree node is collapsed
   */
  @Prop({ reflect: true, mutable: true }) collapsed: boolean = false;

  /**
   * @internal If true, the active indicator is hidden
   */
  @Prop({ reflect: true }) readonly hideIndicator: boolean = false;

  /**
   * @internal Size of all tree nodes. Available sizes are 'm' (default) and 's'
   */
  @Prop({ reflect: true }) readonly size: TreeViewSize = 'm';

  /**
   * @internal If true, the tree nodes are selectable via checkbox
   */
  @Prop({ reflect: true }) readonly selectable: boolean = false;

  /**
   * Only applies when node is selectable. The checkbox will be checked.
   */
  @Prop({ reflect: true, mutable: true }) selected: boolean = false;

  /**
   * @internal Only applies when node is selectable. The checkbox will be marked as indeterminate.
   */
  @Prop({ reflect: true, mutable: true }) indeterminate: boolean = false;

  /**
   * icon to show in front of the text e.g. folder-24
   */
  @Prop({ reflect: true }) readonly icon: string;

  /**
   * sets a custom icon source e.g. '...path/folder-24.svg', overrides icon property if both are set
   */
  @Prop({ reflect: true }) readonly iconSource: string;

  /**
   * sets a custom accessible text for the checkbox
   */
  @Prop({ reflect: true, attribute: 'a11y-label-checkbox' }) readonly a11yLabelCheckbox: string;

  /**
   * sets a custom accessible text for the icon
   */
  @Prop({ reflect: true, attribute: 'a11y-label-icon' }) readonly a11yLabelIcon: string;

  /**
   * URL that the hyperlink points to. Examples: https://www.volkswagen.de/ - tel:05361/12345 - mailto:john.doe@example.com - #anchor1
   */
  @Prop({ reflect: true }) readonly href: string;

  /**
   * where to display the linked URL. On target 'none' no target attribute will be set.
   */
  @Prop({ reflect: true }) readonly target: Target = 'self';

  /**
   * in which relation is the linked URL to the current page
   */
  @Prop({ reflect: true }) readonly rel: Rel;

  /**
   * @internal dispatched when selected state changes, 'selected' is true when node is selected
   */
  @Event({ bubbles: true }) nodeSelectedEvent: EventEmitter<{ selected: boolean }>;

  @State() private isActive = false;
  private childNodeObserver: MutationObserver;

  @Watch('active')
  updateActiveState() {
    this.isActive = this.isActiveNode();
  }

  @Watch('collapsed')
  updateCollapsedState() {
    this.isActive = this.isActiveNode();
  }

  @Watch('selected')
  @Watch('indeterminate')
  updateCheckboxState() {
    const checkbox: HTMLGroupuiCheckboxElement = this.host.shadowRoot
      .querySelectorAll('groupui-checkbox')
      ?.item(0) as HTMLGroupuiCheckboxElement;
    if (checkbox && !this.disabled) {
      checkbox.checked = this.selected;
      checkbox.indeterminate = this.indeterminate;
    }
  }

  @Listen('focus')
  onFocus(event: Event) {
    event.preventDefault();
  }

  componentDidLoad() {
    this.updateActiveState();
    const checkbox = this.host.shadowRoot.querySelector('groupui-checkbox');
    checkbox?.setAttribute('size', this.size);
    checkbox?.setAttribute('tabindex', '-1');
    this.childNodeObserver = new MutationObserver(() => {
      this.updateActiveState();
    });

    const allChildNodes = Array.from(this.host.querySelectorAll('groupui-tree-node'));
    allChildNodes.forEach((node) => {
      this.childNodeObserver?.observe(node, {
        attributes: true,
        attributeFilter: ['active'],
      });
      node.addEventListener('nodeSelectedEvent', () => {
        this.syncSelectionState();
      });
    });
  }

  disconnectedCallback() {
    this.childNodeObserver?.disconnect();
  }

  private toggleCollapse(event: Event): void {
    event.stopPropagation();
    this.collapsed = !this.collapsed;
  }

  private toggleSelection(event: Event): void {
    event.stopPropagation();
    if (this.indeterminate) {
      this.selected = false;
      this.indeterminate = false;
    } else {
      this.selected = !this.selected;
    }
    const checkbox = event.target as HTMLGroupuiCheckboxElement;
    checkbox.checked = this.selected;

    const childNodes = Array.from(this.host.querySelectorAll('groupui-tree-node'));
    childNodes.forEach((node) => {
      if (!node.disabled) {
        node.selected = this.selected;
        if (Array.from(node.querySelectorAll('groupui-tree-node')).some((node) => node.disabled)) {
          node.indeterminate = this.selected;
        } else {
          node.indeterminate = false;
        }
      }
    });
    if (childNodes.some((node) => node.disabled)) {
      this.syncSelectionState();
    }
    this.nodeSelectedEvent.emit({ selected: this.selected });
  }

  private syncSelectionState(): void {
    const allChildNodes = Array.from(this.host.querySelectorAll('groupui-tree-node'));
    this.indeterminate = allChildNodes.some((node) => node.selected) && allChildNodes.some((node) => !node.selected);
    this.selected = allChildNodes.every((node) => node.selected);
  }

  private isLeafNode(): boolean {
    return !this.hasChildNodes() && this.host.parentNode.nodeName === 'GROUPUI-TREE-NODE';
  }

  private hasChildNodes(): boolean {
    return !!this.host.querySelector('groupui-tree-node');
  }

  private isActiveNode(): boolean {
    if (this.collapsed) {
      return !!this.host.querySelector('groupui-tree-node[active]') || this.active;
    } else {
      return this.active;
    }
  }

  private renderCheckbox(): HTMLGroupuiCheckboxElement | null {
    if (!this.selectable) return;
    return (
      <groupui-checkbox
        checked={this.selected}
        indeterminate={this.indeterminate}
        disabled={this.disabled}
        onClick={(event) => this.toggleSelection(event)}
        aria-hidden="true"
      ></groupui-checkbox>
    ) as HTMLGroupuiCheckboxElement;
  }

  private renderChevron(): HTMLGroupuiIconElement | null {
    if (!this.hasChildNodes()) return;
    return (
      <groupui-icon
        name={this.getChevron()}
        onClick={(event) => this.toggleCollapse(event)}
        aria-hidden="true"
      ></groupui-icon>
    ) as HTMLGroupuiIconElement;
  }

  private getChevron(): string {
    const iconSize = this.size === 'm' ? '24' : '16';
    return this.collapsed ? `chevron-right-${iconSize}` : `chevron-down-${iconSize}`;
  }

  private renderIcon(): HTMLGroupuiIconElement | null {
    if (!this.icon && !this.iconSource) return;
    return (
      <groupui-icon name={this.icon} src={this.iconSource} aria-hidden="true"></groupui-icon>
    ) as HTMLGroupuiIconElement;
  }

  private renderA11yLabelCheckbox() {
    if (!this.selectable || !this.a11yLabelCheckbox) return;
    return <span id="a11y-label-checkbox" role="img" aria-label={this.a11yLabelCheckbox} />;
  }

  private renderA11yLabelIcon() {
    if ((!this.icon && !this.iconSource) || !this.a11yLabelIcon) return;
    return <span id="a11y-label-icon" role="img" aria-label={this.a11yLabelIcon} />;
  }

  private getAriaExpanded() {
    if (this.hasChildNodes()) {
      return this.collapsed ? 'false' : 'true';
    }
    return null;
  }

  render() {
    const classes = `node${this.isLeafNode() ? ' is-leaf' : ''}${this.isActive ? ' is-active' : ''}`;

    return (
      <Host
        role="treeitem"
        aria-labelledby="a11y-label-checkbox a11y-label-icon label"
        aria-expanded={this.getAriaExpanded()}
        aria-selected={this.selected ? 'true' : 'false'}
        tabindex={this.disabled ? -1 : 0}
      >
        {this.href ? (
          <a class={classes} href={this.href} target={verifyTarget(this.target)} rel={this.rel} tabindex={-1}>
            {this.renderCheckbox()}
            {this.renderA11yLabelCheckbox()}
            {this.renderChevron()}
            {this.renderIcon()}
            {this.renderA11yLabelIcon()}
            <div id="label">
              <slot name="label"></slot>
            </div>
          </a>
        ) : (
          <span class={classes} tabindex={-1}>
            {this.renderCheckbox()}
            {this.renderA11yLabelCheckbox()}
            {this.renderChevron()}
            {this.renderIcon()}
            {this.renderA11yLabelIcon()}
            <div id="label">
              <slot name="label"></slot>
            </div>
          </span>
        )}
        {!this.collapsed && this.hasChildNodes() && (
          <div class="child-nodes" role="group">
            <slot></slot>
          </div>
        )}
      </Host>
    );
  }
}
